"""Interactive tool pages (markup for assets/js/tools.js) + tools hub."""
from kit import page, page_hero, faq, ad, lead_band, mini_lead, e
from urllib.parse import quote

TOOLS = [
    ("gpa-calculator", "🧮", "GPA Calculator", "Weighted & unweighted GPA with Honors/AP/IB weighting, cumulative GPA and a target planner."),
    ("final-grade-calculator", "🎯", "Final Grade Calculator", "Find the score you need on your final exam to hit your target grade."),
    ("grade-calculator", "📊", "Grade Calculator", "Calculate your class grade from weighted categories like tests, quizzes and homework."),
    ("sat-act-converter", "🔁", "SAT ↔ ACT Converter", "Convert scores between the SAT and ACT using the official concordance table."),
    ("college-cost-calculator", "💸", "College Cost Calculator", "Project future college costs, your savings and the monthly amount to close the gap."),
    ("credit-tracker", "✅", "Graduation Credit Tracker", "Track credits by subject area and see how close you are to graduating."),
    ("study-timer", "⏱️", "Study Timer (Pomodoro)", "Focus in 25-minute sprints with automatic short and long breaks."),
    ("flashcards", "🃏", "Flashcard Maker", "Create, flip, shuffle and save your own flashcard decks — no sign-up."),
]
REL = [(t[2], f"@@/tools/{t[0]}/") for t in TOOLS]


def tool_page(slug, title, desc, kw, tool_html, explainer, faqs, cta_need="Tutoring", cta_text="Want to raise it? Get a free tutoring match →"):
    crumbs = [("Tools", "@@/tools/"), (title, "")]
    fq, fs = faq(faqs)
    others = "".join(f'<a class="card" href="@@/tools/{s}/"><div class="ico">{i}</div><h3>{t}</h3><p>{d}</p></a>' for s, i, t, d in TOOLS if s != slug)[:4000]
    body = page_hero(f"{title}", desc, crumbs, eyebrow="Free tool · No sign-up · Saves on your device")
    body += f'''<div class="wrap"><div class="layout"><div>{tool_html}
<p class="small muted" style="margin-top:10px">Results are estimates for planning. Your school’s official records and policies always take priority.</p>
<div class="callout t"><p><a href="@@/get-matched/?need={quote(cta_need)}"><strong>{cta_text}</strong></a></p></div>
<div class="prose">{explainer}{ad()}{fq}</div></div>
<aside><div class="aside-sticky">{mini_lead(title, cta_need)}<div class="aside-box"><h4>More free tools</h4><ul>{"".join(f'<li><a href="{u}">{e(t)}</a></li>' for t, u in REL if t != title)}</ul></div></div></aside></div>
<section><h2>Try another tool</h2><div class="grid g4">{"".join(f'<a class="card" href="@@/tools/{s}/"><div class="ico">{i}</div><h3>{t}</h3></a>' for s, i, t, d in TOOLS if s != slug)}</div></section></div>'''
    app = {"@context": "https://schema.org", "@type": "WebApplication", "name": f"{title} — High.School", "applicationCategory": "EducationalApplication", "operatingSystem": "Any", "offers": {"@type": "Offer", "price": "0", "priceCurrency": "USD"}, "description": desc}
    page(f"tools/{slug}/", title, desc, body, crumbs, [fs, app], kw, tools=True)


def build():
    tool_page("gpa-calculator", "GPA Calculator", "Free high school GPA calculator: weighted and unweighted GPA, Honors/AP/IB/Dual Enrollment weighting, cumulative GPA and a target planner.", "gpa calculator, weighted gpa calculator, high school gpa calculator, cumulative gpa",
        '''<div class="tool" id="gpa-tool"><h2 style="margin-top:0">This semester’s courses</h2><div style="overflow-x:auto"><table><thead><tr><th>Course</th><th>Grade</th><th>Level</th><th>Credits</th><th></th></tr></thead><tbody id="gpa-rows"></tbody></table></div>
<p style="display:flex;gap:8px;flex-wrap:wrap"><button type="button" class="btn btn-ink btn-sm" id="gpa-add">+ Add course</button><button type="button" class="btn btn-ghost btn-sm" id="gpa-reset">Reset</button></p>
<details><summary>Add previous semesters (cumulative GPA)</summary><div class="row2"><div class="field"><label for="gpa-prior">Prior cumulative GPA (unweighted)</label><input id="gpa-prior" type="number" step="0.01" min="0" max="5" placeholder="e.g. 3.40"></div><div class="field"><label for="gpa-prior-cr">Prior credits earned</label><input id="gpa-prior-cr" type="number" step="0.5" min="0" placeholder="e.g. 12"></div></div></details>
<div class="result"><div><b id="gpa-u">0.00</b><span>Unweighted GPA (4.0 scale)</span></div><div><b id="gpa-w">0.00</b><span>Weighted GPA</span></div><div><b id="gpa-c">0.00</b><span>Cumulative (unweighted)</span></div><div><b id="gpa-cr">0</b><span>Credits this term</span></div></div>
<details><summary>🎯 Target GPA planner</summary><div><div class="row2"><div class="field"><label for="gpa-target">Target cumulative GPA</label><input id="gpa-target" type="number" step="0.01" min="0" max="4" value="3.5"></div><div class="field"><label for="gpa-next">Credits you’ll take next term</label><input id="gpa-next" type="number" step="0.5" min="0.5" value="6"></div></div><p id="gpa-plan" class="form-status"></p></div></details></div>''',
        '''<h2>How GPA is calculated</h2><p>Each letter grade converts to grade points on a 4.0 scale (A = 4.0, B = 3.0, C = 2.0, D = 1.0, F = 0, with plus/minus steps). Multiply each course’s points by its credits, add them up, and divide by total credits. That’s your <strong>unweighted GPA</strong>.</p>
<p><strong>Weighted GPA</strong> adds a bonus for harder courses — commonly <strong>+0.5 for Honors</strong> and <strong>+1.0 for AP, IB or dual-enrollment</strong> — so an A in AP Biology counts as 5.0. Schools differ: some cap weighting, some use 4.33 for A+, and some don’t weight at all. Colleges often recalculate GPA their own way, so report what your transcript shows.</p>
<table><thead><tr><th>Grade</th><th>Points</th><th>Grade</th><th>Points</th></tr></thead><tbody><tr><td>A / A+</td><td>4.0</td><td>C</td><td>2.0</td></tr><tr><td>A−</td><td>3.7</td><td>C−</td><td>1.7</td></tr><tr><td>B+</td><td>3.3</td><td>D+</td><td>1.3</td></tr><tr><td>B</td><td>3.0</td><td>D</td><td>1.0</td></tr><tr><td>B−</td><td>2.7</td><td>D−</td><td>0.7</td></tr><tr><td>C+</td><td>2.3</td><td>F</td><td>0.0</td></tr></tbody></table>
<h2>What is a good high school GPA?</h2><p>The answer depends on your goals. A <strong>3.0</strong> unweighted meets the minimum for many state universities and scholarships; <strong>3.5+</strong> is competitive for many selective colleges; the most selective colleges typically see <strong>3.9+ unweighted</strong> with a rigorous schedule. Upward trends matter too — admissions readers notice improvement.</p>
<h2>How to raise your GPA</h2><ul><li>Focus on the class with the most credits and the most room to improve — it moves the average most.</li><li>Use the <a href="@@/tools/final-grade-calculator/">final grade calculator</a> to see what you need on upcoming exams.</li><li>Ask about retake, test-correction or extra-credit policies early in the term.</li><li>Fix study habits, not just effort: see <a href="@@/guides/how-to-study/">how to study effectively</a>.</li></ul>''',
        [("What’s the difference between weighted and unweighted GPA?", "Unweighted GPA treats every class the same on a 4.0 scale. Weighted GPA adds points for Honors, AP, IB or dual-enrollment classes, so it can exceed 4.0."),
         ("Do colleges look at weighted or unweighted GPA?", "Both, and many recalculate using only core academic classes. They also look at course rigor — the difficulty of your schedule relative to what your school offers."),
         ("Is my data saved?", "Your courses are saved only in your own browser (local storage) so you can come back later. Nothing is uploaded.")])

    tool_page("final-grade-calculator", "Final Grade Calculator", "What do I need on my final? Enter your current grade, the final exam’s weight and your target to see the exact score you need.", "final grade calculator, what do i need on my final, final exam calculator",
        '''<div class="tool" id="final-tool"><div class="grid g3"><div class="field"><label for="fg-cur">Current grade (%)</label><input id="fg-cur" type="number" value="86" min="0" max="120"></div><div class="field"><label for="fg-w">Final exam weight (%)</label><input id="fg-w" type="number" value="20" min="1" max="99"></div><div class="field"><label for="fg-t">Target grade (%)</label><input id="fg-t" type="number" value="90" min="0" max="120"></div></div>
<div class="result"><div><b id="fg-out">—</b><span>Score needed on the final</span></div><div><b id="fg-best">—</b><span>Grade if you ace it (100%)</span></div><div><b id="fg-worst">—</b><span>Grade if you score 0%</span></div></div><p id="fg-note" class="form-status" style="margin-top:10px"></p></div>''',
        '''<h2>The formula</h2><p>If your final is worth <em>w</em> (as a decimal) of your grade, then: <span class="kbd">Needed = (Target − Current × (1 − w)) ÷ w</span>. Example: current 86%, final worth 20%, target 90% → (90 − 86 × 0.8) ÷ 0.2 = <strong>106%</strong>. That’s out of reach without extra credit — so the plan would be to aim for an 87–88% instead, or raise the current grade first.</p>
<h2>Making the most of your final</h2><ol><li>Start reviewing 10–14 days out with short daily sessions.</li><li>Rank units by points at stake and by how weak you are; study the overlap first.</li><li>Do practice tests under timed conditions — then review every miss.</li><li>Sleep the night before; memory consolidates during sleep.</li></ol><p>More tactics: <a href="@@/guides/how-to-study/">How to Study Effectively</a>.</p>''',
        [("What if I need more than 100%?", "The target isn’t reachable with the final alone. Ask your teacher about extra credit, test corrections or replacement policies, or adjust your target."),
         ("What if my class uses points instead of percentages?", "Convert to a percentage: points earned ÷ points possible × 100, and the final’s weight = final points ÷ total course points.")])

    tool_page("grade-calculator", "Weighted Grade Calculator", "Calculate your class grade from weighted categories — tests, quizzes, homework, labs and projects — and see the letter grade instantly.", "grade calculator, weighted grade calculator, class grade calculator",
        '''<div class="tool" id="cat-tool"><div style="overflow-x:auto"><table><thead><tr><th>Category</th><th>Weight %</th><th>Your score %</th><th></th></tr></thead><tbody id="cat-rows"></tbody></table></div><p><button type="button" class="btn btn-ink btn-sm" id="cat-add">+ Add category</button></p>
<div class="result"><div><b id="cat-out">—</b><span>Class grade</span></div><div><b id="cat-l">—</b><span>Letter grade</span></div><div><b id="cat-w">—</b><span>Total weight</span></div></div><p id="cat-warn" class="small muted"></p></div>''',
        '''<h2>How weighted grades work</h2><p>Teachers often group work into categories with different weights — for example Tests 40%, Quizzes 20%, Homework 20%, Labs 20%. Your grade is the weighted average: multiply each category score by its weight, add them, and divide by the total weight. Find your weights in the course syllabus or grade portal.</p>
<p>Because tests usually carry the most weight, a 10-point improvement on tests raises the class grade far more than perfect homework does. Use this calculator to test “what if” scenarios before deciding where to spend study time.</p>''',
        [("What letter-grade scale does this use?", "A common US scale: 93+ A, 90–92 A−, 87–89 B+, 83–86 B, 80–82 B−, and so on down to below 60 = F. Your school’s scale may differ."),
         ("What if weights don’t add to 100%?", "The calculator normalizes them automatically, which matches how most grade portals handle partially graded terms.")])

    tool_page("sat-act-converter", "SAT ↔ ACT Score Converter", "Convert SAT to ACT and ACT to SAT scores using the official concordance tables, with an approximate SAT percentile band.", "sat to act conversion, act to sat, sat act concordance",
        '''<div class="tool" id="satact-tool"><div class="grid g2"><div><div class="field"><label for="sa-sat">SAT total (400–1600)</label><input id="sa-sat" type="number" min="400" max="1600" step="10" value="1250"></div><div class="result"><div><b id="sa-act-out">—</b><span>Equivalent ACT composite</span></div><div><b id="sa-pct" style="font-size:1.4rem">—</b><span>Approx. SAT percentile</span></div></div></div>
<div><div class="field"><label for="sa-act">ACT composite (1–36)</label><input id="sa-act" type="number" min="1" max="36" value="28"></div><div class="result"><div><b id="sa-sat-out">—</b><span>Equivalent SAT total</span></div></div></div></div></div>''',
        '''<h2>About the concordance</h2><p>College Board and ACT publish an official concordance that links scores on the two tests — it’s what colleges use to compare applicants. A 1250 SAT, for example, corresponds to a 26 ACT. Use it to decide which test you’re stronger on after taking a practice test of each.</p>
<table><thead><tr><th>ACT</th><th>SAT</th><th>ACT</th><th>SAT</th></tr></thead><tbody><tr><td>36</td><td>1570–1600</td><td>26</td><td>1230–1250</td></tr><tr><td>34</td><td>1490–1520</td><td>24</td><td>1160–1190</td></tr><tr><td>32</td><td>1420–1440</td><td>22</td><td>1100–1120</td></tr><tr><td>30</td><td>1360–1380</td><td>20</td><td>1030–1050</td></tr><tr><td>28</td><td>1300–1320</td><td>18</td><td>960–980</td></tr></tbody></table>
<p>Percentile bands are approximate and for orientation only; your official score report shows your exact percentiles. The ACT updated its format in 2025; colleges continue to use the concordance to compare scores. See <a href="@@/test-prep/sat-vs-act/">SAT vs ACT</a>.</p><p class="small muted">SAT® is a trademark registered by the College Board. ACT® is a registered trademark of ACT Education Corp. Neither is affiliated with High.School.</p>''',
        [("Is a 1200 SAT good?", "A 1200 is above the national average and corresponds to about a 25 ACT. It’s competitive at many public universities."),
         ("Which is easier to improve, SAT or ACT?", "It depends on your strengths. Many students see fast gains on ACT English or SAT Reading & Writing grammar questions because they rely on learnable rules.")],
        cta_need="Test prep (SAT/ACT/AP)", cta_text="Want a higher score? Get a free test-prep match →")

    tool_page("college-cost-calculator", "College Cost & Savings Calculator", "Project the future cost of college with inflation, estimate your savings growth, and see the monthly amount needed to close the gap.", "college cost calculator, college savings calculator, 529 calculator, how much to save for college",
        '''<div class="tool" id="cost-tool"><div class="grid g3"><div class="field"><label for="cc-cost">Today’s yearly cost ($)</label><input id="cc-cost" type="number" value="28000" step="500"><small>Tuition + room/board + fees</small></div><div class="field"><label for="cc-aid">Expected grants/scholarships per year ($)</label><input id="cc-aid" type="number" value="6000" step="500"></div><div class="field"><label for="cc-years">Years until college starts</label><input id="cc-years" type="number" value="4" min="0" max="18"></div>
<div class="field"><label for="cc-len">Years of college</label><input id="cc-len" type="number" value="4" min="1" max="6"></div><div class="field"><label for="cc-inf">College cost inflation (%/yr)</label><input id="cc-inf" type="number" value="4" step="0.5"></div><div class="field"><label for="cc-sav">Current savings ($)</label><input id="cc-sav" type="number" value="10000" step="500"></div>
<div class="field"><label for="cc-mo">Monthly contribution ($)</label><input id="cc-mo" type="number" value="250" step="25"></div><div class="field"><label for="cc-ret">Expected return (%/yr)</label><input id="cc-ret" type="number" value="5" step="0.5"></div></div>
<div class="result"><div><b id="cc-total">—</b><span>Projected total cost (after aid)</span></div><div><b id="cc-fv">—</b><span>Projected savings at start</span></div><div><b id="cc-gap">—</b><span>Funding gap</span></div><div><b id="cc-need">—</b><span>Monthly to close gap</span></div></div></div>''',
        '''<h2>How this estimate works</h2><p>We grow today’s net yearly cost (cost minus expected grants) by your inflation rate for each year until and during college, then add the years together. Savings grow monthly at your expected return. The gap is what loans, work-study, family income or additional savings would need to cover.</p>
<h2>Ways to shrink the gap</h2><ul><li><strong>Apply for aid every year</strong> — file the <a href="@@/college/financial-aid/">FAFSA</a> and any required CSS Profile.</li><li><strong>Stack scholarships</strong> — track them with our <a href="@@/college/scholarships/">scholarship tracker</a>.</li><li><strong>Use each college’s Net Price Calculator</strong> — required on US college websites and often far lower than the sticker price.</li><li><strong>Earn credit early</strong> through AP, IB or dual enrollment.</li><li><strong>Consider community college transfer pathways</strong> for the first two years.</li></ul><p class="small muted">Educational estimate only — not financial advice. Investment returns are not guaranteed.</p>''',
        [("What is a good college cost inflation rate to assume?", "Many planners use 3–5% per year. Use a higher rate to be conservative."),
         ("What’s a 529 plan?", "A US tax-advantaged education savings account. Earnings grow tax-free when used for qualified education expenses. Plans vary by state.")],
        cta_need="College counseling", cta_text="Want help finding aid and scholarships? Get a free college-counseling match →")

    tool_page("credit-tracker", "Graduation Credit Tracker", "Track your high school credits by subject area — English, math, science, social studies, languages, arts, PE and electives — and see what’s left to graduate.", "high school credits, graduation requirements, credit tracker, how many credits to graduate",
        '''<div class="tool" id="credit-tool"><div style="overflow-x:auto"><table><thead><tr><th>Subject area</th><th>Required</th><th>Earned</th><th>Progress</th><th></th></tr></thead><tbody id="credit-rows"></tbody></table></div>
<p style="display:flex;gap:8px;flex-wrap:wrap"><button type="button" class="btn btn-ink btn-sm" id="ct-add">+ Add area</button><button type="button" class="btn btn-ghost btn-sm" id="ct-reset">Reset to sample</button></p>
<div class="result"><div><b id="ct-got">0</b><span>Credits earned</span></div><div><b id="ct-req">0</b><span>Credits required</span></div><div><b id="ct-left">0</b><span>Credits remaining</span></div><div><b id="ct-pct">0%</b><span>Complete</span></div></div></div>''',
        '''<h2>How many credits do you need to graduate?</h2><p>Requirements are set by each state and district, and typically range from about <strong>20 to 28 credits</strong>. A common pattern is 4 English, 3–4 math, 3 science, 3 social studies, 1–2 world language, 1 fine arts, 1–2 PE/health, plus electives. Some states add requirements such as personal finance, civics tests or community service. Replace our sample numbers with your school’s official list (found in the course catalog or from your counselor).</p>
<h2>Behind on credits?</h2><p>You have options: summer school, <strong>credit recovery</strong> courses, online courses, or dual enrollment. Our <a href="@@/online-high-school/">Online High School & Diploma guide</a> explains each path and how to check accreditation.</p>''',
        [("What is a credit?", "Usually one credit equals a full-year course that meets daily; a semester course is often 0.5 credit. Some schools use different systems, so check your catalog."),
         ("Can I graduate early?", "Many districts allow early graduation if all credits and tests are complete. Talk to your counselor by 10th grade to plan.")],
        cta_need="Online diploma / credit recovery", cta_text="Behind on credits? Get free advice on credit-recovery and online options →")

    tool_page("study-timer", "Study Timer (Pomodoro)", "A free Pomodoro study timer: 25-minute focus sessions with automatic 5-minute and 15-minute breaks, custom lengths and a session counter.", "pomodoro timer, study timer, focus timer, study with me",
        '''<div class="tool center" id="timer-tool"><div class="toggle" role="group" aria-label="Timer mode"><button type="button" data-mode="focus" class="active">Focus</button><button type="button" data-mode="short">Short break</button><button type="button" data-mode="long">Long break</button></div>
<div class="timer-face" id="tm-face" aria-live="off">25:00</div><p style="display:flex;gap:10px;justify-content:center"><button type="button" class="btn btn-primary" id="tm-start">Start</button><button type="button" class="btn btn-ghost" id="tm-reset">Reset</button></p>
<p>Focus sessions completed: <strong id="tm-sessions">0</strong> · <button type="button" class="btn btn-sm btn-ghost" id="tm-clear">Clear</button></p>
<details style="text-align:left"><summary>Customize lengths (minutes)</summary><div class="grid g3"><div class="field"><label for="tm-focus">Focus</label><input class="tm-set" id="tm-focus" type="number" value="25" min="1" max="120"></div><div class="field"><label for="tm-short">Short break</label><input class="tm-set" id="tm-short" type="number" value="5" min="1" max="60"></div><div class="field"><label for="tm-long">Long break</label><input class="tm-set" id="tm-long" type="number" value="15" min="1" max="60"></div></div></details></div>''',
        '''<h2>How the Pomodoro Technique works</h2><p>Developed by Francesco Cirillo, the method breaks work into focused intervals — traditionally 25 minutes — separated by short breaks. After four sessions, take a longer break. The timer creates urgency, makes big assignments feel manageable, and builds a measurable habit.</p>
<h2>Tips for better focus sessions</h2><ul><li>Write the single task for the session before you press Start.</li><li>Phone in another room — notifications cost minutes of refocus time each.</li><li>During breaks, move: stretch, refill water, look away from screens.</li><li>Pair sessions with <a href="@@/tools/flashcards/">flashcards</a> or practice problems — active work, not re-reading.</li></ul>''',
        [("Is 25 minutes the right length?", "It’s a good start. Many high schoolers move to 40–50 minute sessions for deep work like essays once focus improves. Use the custom settings."),
         ("Does the timer work in the background?", "Yes, while this tab stays open. A short tone plays when a session ends.")])

    tool_page("flashcards", "Flashcard Maker", "Make and study your own flashcards online — flip, shuffle, bulk import from notes, and save decks on your device. Free, no account.", "flashcard maker, online flashcards, study flashcards, free flashcards",
        '''<div class="tool" id="flash-tool"><div class="flash" id="fc-card" tabindex="0" role="button" aria-label="Flashcard — press to flip"><div class="flash-inner"><div class="flash-face" id="fc-front"></div><div class="flash-face flash-back" id="fc-back"></div></div></div>
<p style="display:flex;gap:8px;flex-wrap:wrap;justify-content:center;align-items:center"><button type="button" class="btn btn-ghost btn-sm" id="fc-prev">← Prev</button><strong id="fc-pos">0 / 0</strong><button type="button" class="btn btn-ghost btn-sm" id="fc-next">Next →</button><button type="button" class="btn btn-ink btn-sm" id="fc-shuffle">Shuffle</button><button type="button" class="btn btn-sm" id="fc-del" style="color:var(--coral-d)">Delete card</button></p>
<form id="fc-form" class="row2"><div class="field"><label for="fc-f">Front (term)</label><input id="fc-f" type="text" required></div><div class="field"><label for="fc-b">Back (definition)</label><input id="fc-b" type="text" required></div><button class="btn btn-primary btn-sm" type="submit">+ Add card</button></form>
<details><summary>Bulk import from notes</summary><div><div class="field"><label for="fc-bulk">One card per line: <span class="kbd">term - definition</span></label><textarea id="fc-bulk" placeholder="Photosynthesis - converts light energy into chemical energy&#10;Mitosis - cell division producing two identical cells"></textarea></div><button type="button" class="btn btn-ink btn-sm" id="fc-import">Import cards</button></div></details></div>''',
        '''<h2>Why flashcards work (when used right)</h2><p>Flashcards force <strong>retrieval practice</strong> — pulling information out of memory — one of the most effective study strategies known. Combine it with <strong>spacing</strong> (reviewing over several days) for long-term retention.</p><ul><li>Say the answer out loud before flipping.</li><li>Keep cards small: one idea per card.</li><li>Shuffle so you can’t rely on order.</li><li>Delete cards you know cold; spend time on the hard ones.</li></ul><p>Keyboard: <span class="kbd">←</span> <span class="kbd">→</span> to move, <span class="kbd">Space</span> to flip.</p>''',
        [("Are my cards saved?", "Yes — in your own browser on this device. Clearing browser data deletes them."),
         ("Can I share a deck?", "Not yet. Sharing and pre-made decks for every subject are on our roadmap.")])

    hub = page_hero("Free Student Tools", "Calculators and study tools built for high school — fast, private (saved only on your device) and free forever.", [("Tools", "")], eyebrow="8 tools · No sign-up")
    hub += '<div class="wrap"><section><div class="grid g4">' + "".join(f'<a class="card" href="@@/tools/{s}/"><div class="ico">{i}</div><h3>{t}</h3><p>{d}</p></a>' for s, i, t, d in TOOLS) + '</div></section>'
    hub += '''<section class="prose narrow"><h2>Built for real decisions</h2><p>Every tool answers a question students and parents actually ask: <em>What’s my GPA? What do I need on the final? Which test should I take? Can we afford this college? Am I on track to graduate?</em> Each one explains its math so you can trust the result — and your data never leaves your browser.</p>
<p>Want a tool we don’t have yet? <a href="@@/contact/">Tell us</a> — reader requests shape our roadmap.</p></section></div>'''
    page("tools/", "Free High School Calculators & Study Tools", "Free GPA calculator, final grade calculator, weighted grade calculator, SAT-ACT converter, college cost calculator, credit tracker, Pomodoro timer and flashcards.", hub + lead_band(), [("Tools", "")], keywords="gpa calculator, grade calculator, student tools")
